# Export the trained control law (physical law + MLP residual ensemble + nonlinear globals)
# to ../dsp/kobol_vcf_law.h, and check the C++ evaluation against Python.
import numpy as np
W = np.load('law_mlp.npz'); PP = np.load('law_phys.npy'); O = np.load('oscfit.npy', allow_pickle=True).item()
M = sorted({k.split('_')[0] for k in W.files if k.startswith('m')})
def arr(a): return '{' + ', '.join(f'{v:.9g}' for v in np.ravel(a)) + '}'
H = W['m0_W0'].shape[1]
lines = [
'// GENERATED by vcf-model/export_law.py from the RSF Kobol recordings -- do not edit by hand.',
'// Control law of the Kobol VCF: (cutoff CV, resonance CV) in volts at the MCV24 scale',
'// (MIDI value * 10/127) -> SSM2040 parameters (fc Hz, feedback K, pass-band gain dB).',
'// = physical law (exponential converter + linear resonance current) + neural residual',
f'//   (ensemble of {len(M)} MLPs 2-{H}-{H}-3, tanh), plus the global nonlinear constants.',
'#pragma once',
'#include <cmath>',
'#include <algorithm>',
'namespace kobol { namespace vcflaw {',
f'constexpr double kDrive = {O["drive"]:.9g};   // input level re the SSM2040 cell tanh knee',
f'constexpr double kFbKnee = {O["q"]:.9g};   // resonance CA3080 knee re the cells',
f'constexpr int kH = {H}, kM = {len(M)};',
f'constexpr double kPhys[12] = {arr(PP)};',
f'constexpr double kSC[3] = {arr(W["SC"])};',
]
for j, nm in enumerate(['W0', 'b0', 'W1', 'b1', 'W2', 'b2']):
    lines.append(f'constexpr double k{nm}[kM][{np.size(W["m0_"+nm])}] = {{' + ', '.join(arr(W[f"{m}_{nm}"]) for m in M) + '};')
lines += ['''
inline double softplus(double z) { return z > 30 ? z : std::log1p(std::exp(z)); }

struct Params { double fc, K, gainDb; };

// cutoffV, resV: control voltages (0..10 V nominal; the measured grid spans 1.18..10 V)
inline Params evaluate(double cutoffV, double resV) {
    const double* p = kPhys;
    const double vc = cutoffV, vr = resV;
    double y[3] = {
        p[0] + p[1] * vc - softplus(p[2] * (vc - p[3])) * p[4] / p[2],
        p[5] * softplus(p[6] * (vr - p[7])) / p[6] + p[8] * vr * vc / 10.0,
        p[9] + p[10] * vc + p[11] * vc * vc };
    const double x0 = (vc - 5.0) / 3.0, x1 = (vr - 5.0) / 3.0;
    for (int m = 0; m < kM; ++m) {
        double h1[kH], h2[kH];
        for (int j = 0; j < kH; ++j) h1[j] = std::tanh(x0 * kW0[m][j] + x1 * kW0[m][kH + j] + kb0[m][j]);
        for (int j = 0; j < kH; ++j) { double s = kb1[m][j]; for (int i = 0; i < kH; ++i) s += h1[i] * kW1[m][i * kH + j]; h2[j] = std::tanh(s); }
        for (int o = 0; o < 3; ++o) { double s = kb2[m][o]; for (int i = 0; i < kH; ++i) s += h2[i] * kW2[m][i * 3 + o]; y[o] += s / kSC[o] / kM; }
    }
    return { 1000.0 * std::exp2(y[0]), std::max(0.0, y[1]), y[2] };
}
}} // namespace kobol::vcflaw
''']
open('../dsp/kobol_vcf_law.h', 'w').write('\n'.join(lines))
print('wrote ../dsp/kobol_vcf_law.h')
